/// <summary>Returns the arithmetic mean of a nonempty finite list.</summary>
/// <exception cref="ArgumentException">The list is null or empty.</exception>
/// <exception cref="ArgumentOutOfRangeException">A value is non-finite.</exception>
public static double Mean(IReadOnlyList<double> values)
{
    if (values is null || values.Count == 0) throw new ArgumentException("A nonempty list is required.", nameof(values));
    double sum = 0;
    foreach (var value in values)
    {
        if (!double.IsFinite(value)) throw new ArgumentOutOfRangeException(nameof(values));
        sum += value;
    }
    return sum / values.Count;
}

